    "content": "@use '@angular/material' as mat;\n@use 'sass:map';\n@use 'sass:math';\n@use './sizes' as sizes;\n@use './theme-colors' as theme-colors;\n\n@mixin configure-check-box($height) {\n  @include mat.checkbox-overrides(\n    (\n      state-layer-size: $height,\n      touch-target-size: $height + 8px,\n    )\n  );\n}\n\n@mixin check-box-overrides($sizes) {\n  @each $size, $height in $sizes {\n    &.sz-#{$size} {\n      @include configure-check-box($height);\n    }\n  }\n}\n\nmat-checkbox {\n  // use function to apply overrides for all sizes\n  @include check-box-overrides(sizes.$form-field-sizes);\n\n  // if no size attribute, use the medium size as default\n  &:not(.sz-small):not(.sz-medium):not(.sz-large):not(.sz-xlarge) {\n    $medium-height: map.get(sizes.$form-field-sizes, medium);\n    @include configure-check-box($medium-height);\n  }\n\n   &.destructive {\n    @include mat.checkbox-overrides(\n      (\n        selected-hover-icon-color: map.get(theme-colors.$error-palette, 40),\n        selected-icon-color: map.get(theme-colors.$error-palette, 40),\n        selected-focus-icon-color: map.get(theme-colors.$error-palette, 40),\n        selected-pressed-icon-color: map.get(theme-colors.$error-palette, 40),\n        selected-checkmark-color: map.get(theme-colors.$error-palette, 90),\n        selected-focus-state-layer-color: color-mix(in srgb, map.get(theme-colors.$error-palette, 40) 8%, map.get(theme-colors.$neutral-palette, 96)),\n        selected-pressed-state-layer-color: color-mix(in srgb, map.get(theme-colors.$error-palette, 40) 12%, map.get(theme-colors.$neutral-palette, 96)),\n        unselected-pressed-state-layer-color: map.get(theme-colors.$error-palette, 40)\n      )\n    );\n  }\n}\n\n",
