    "content": "@use '@angular/material' as mat;\n@use 'sass:map';\n@use 'sass:math';\n@use './sizes' as sizes;\n@use './mat-button' as button-overrides;\n\n@mixin configure-form-field($height) {\n  $input-height: calc($height * 2 / 3);\n  // if size is small and not appearance outline, set height to 40px;\n\n  @include mat.form-field-overrides(\n    (\n      container-height: $height,\n      container-text-size: 1em,\n      filled-label-text-size: 0.9rem,\n      container-vertical-padding: math.div(($height - $input-height), 2),\n      filled-with-label-container-padding-top: calc(($height - $input-height) * 3 / 4),\n      filled-with-label-container-padding-bottom: calc(($height - $input-height) / 4),\n    )\n  );\n  &.sh-squircle,\n  &:not(.sh-square):not(.sh-squircle) {\n    @include mat.form-field-overrides(\n      (\n        // BORDER RADIUS OF FORM FIELD\n        outlined-container-shape: math.div($height, 8),\n        filled-container-shape: math.div($height, 8)\n      )\n    );\n  }\n  &.sh-square {\n    @include mat.form-field-overrides(\n      (\n        // BORDER RADIUS OF FORM FIELD\n        outlined-container-shape: 0px,\n        filled-container-shape: 0px\n      )\n    );\n  }\n\n  &.no-hint, &.no-error {\n    .mat-mdc-form-field-subscript-wrapper {\n      display: none;\n    }\n  }\n\n  .mat-mdc-form-field-icon-prefix > .mat-icon, .mat-mdc-form-field-icon-suffix > .mat-icon {\n    padding: 0 calc($height / 8);\n  }\n  input.mat-mdc-input-element.mat-mdc-input-element {\n    height: $input-height;\n  }\n  .mat-mdc-text-field-wrapper {\n    padding-left: calc($height/4);\n  }\n  .mat-mdc-form-field-flex,\n  .mat-mdc-text-field-wrapper,\n  .mat-mdc-form-field-infix {\n    // WE want to target only input elements and not text areas\n    &:has(input[matInput]) {\n      height: $height;\n    }\n  }\n\n  mat-select,\n  mat-select > .mat-mdc-select-trigger {\n    min-height: $input-height;\n  }\n  mat-option {\n    min-height: $height;\n  }\n}\n\n@mixin form-field-overrides($sizes) {\n  align-self: flex-start;\n\n  @each $size, $height in $sizes {\n    &.sz-#{$size} {\n      @include configure-form-field($height);\n    }\n  }\n}\n\n@mixin form-field-button-without-size-config($height) {\n  button {\n    &[matButton],\n    &[matIconButton],\n    &[matFab],\n    &[matMiniFab] {\n      // doesn't have size class, use the size of the form field to determine the button size\n      &:not(.sz-xsmall):not(.sz-small):not(.sz-medium):not(.sz-large):not(.sz-xlarge) {\n        @include button-overrides.configure-button($height);\n      }\n    }\n  }\n}\n\nmat-form-field {\n  // use function to apply overrides for all sizes\n  @include form-field-overrides(sizes.$form-field-sizes);\n\n  // apply button overrides to the buttons inside the form field based on form-field size\n  @each $size, $height in sizes.$form-field-sizes {\n    &.sz-#{$size} {\n      @include form-field-button-without-size-config($height);\n    }\n  }\n  // if no size class, use the medium size as default\n  &:not(.sz-small):not(.sz-medium):not(.sz-large):not(.sz-xlarge) {\n    $medium-height: map.get(sizes.$form-field-sizes, medium);\n    @include configure-form-field($medium-height);\n    @include form-field-button-without-size-config($medium-height);\n  }\n}\n\n\n",
